import{_ as t,o as a,c as o,ag as s}from"./chunks/framework.BaNuf0sO.js";const p=JSON.parse('{"title":"MenuItemSub（递归子菜单分组件）","description":"","frontmatter":{},"headers":[],"relativePath":"docs/core/src/components/menu/docs/README-MenuItemSub.md","filePath":"docs/core/src/components/menu/docs/README-MenuItemSub.md"}'),i={name:"docs/core/src/components/menu/docs/README-MenuItemSub.md"};function n(r,e,l,d,u,c){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="menuitemsub-递归子菜单分组件" tabindex="-1">MenuItemSub（递归子菜单分组件） <a class="header-anchor" href="#menuitemsub-递归子菜单分组件" aria-label="Permalink to &quot;MenuItemSub（递归子菜单分组件）&quot;">​</a></h1><blockquote><p>ElSubMenu 递归分组：含 children 的节点递归渲染子菜单、叶子渲染 ElMenuItem；由 MenuTree 递归自用。 范式页：<code>packages/core/src/components/menu/MenuTree.vue</code>（内部消费方）</p></blockquote><h2 id="定位" tabindex="-1">定位 <a class="header-anchor" href="#定位" aria-label="Permalink to &quot;定位&quot;">​</a></h2><ul><li>递归子菜单分组件：节点含 <code>children</code> → <code>ElSubMenu</code> + 递归子级；叶子 → <code>ElMenuItem</code></li><li>组件自引用：<code>MenuItemSub</code> prop 传入组件自身，供 children 递归再实例化</li><li>一般由 <code>MenuTree</code> 内部使用，独立消费场景少见</li><li><strong>两种形态下的角色</strong>： <ul><li>MenuTree <code>groupMode=false</code>（树形）→ 承接 <strong>L1 及以下</strong>全部有子项的节点</li><li>MenuTree <code>groupMode=true</code>（分组）→ L1 已被 <code>ElMenuItemGroup</code> 分组标题接管，本组件<strong>只承接 L2 及更深</strong>层级（即「分组标题内的手风琴」）。分组标题只吃掉一层，深层级仍归本组件——这是分组形态下三级菜单混合渲染的实现落点</li></ul></li></ul><h2 id="徽标-badge" tabindex="-1">徽标（badge） <a class="header-anchor" href="#徽标-badge" aria-label="Permalink to &quot;徽标（badge）&quot;">​</a></h2><p>本组件渲染的 ElSubMenu 标题与其下叶子项，同样以各自的 <code>path</code> 为 key 查 <code>bridge.badge</code> 渲染角标，规则与 MenuTree 一致（未命中零影响、不挤压文案、不聚合）。见 <a href="/done-coding-showcase/docs/core/src/components/menu/docs/README-MenuTree.html#徽标badge">README-MenuTree.md</a>。</p><h2 id="快速上手-最小可用" tabindex="-1">快速上手（最小可用） <a class="header-anchor" href="#快速上手-最小可用" aria-label="Permalink to &quot;快速上手（最小可用）&quot;">​</a></h2><p>MenuTree 内部驱动（menu/MenuTree.vue 片段）：</p><div class="language-html vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">html</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">&lt;</span><span style="--shiki-light:#B31D28;--shiki-light-font-style:italic;--shiki-dark:#FDAEB7;--shiki-dark-font-style:italic;">MenuItemSub</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> :menu</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;menu!&quot;</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> :MenuItemSub</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;MenuItemSub&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> /&gt;</span></span></code></pre></div><h2 id="能力边界-按需使用" tabindex="-1">能力边界 / 按需使用 <a class="header-anchor" href="#能力边界-按需使用" aria-label="Permalink to &quot;能力边界 / 按需使用&quot;">​</a></h2><ul><li><strong>内部递归件，勿直用：MenuTree 递归自用的分组件，独立消费场景少见。</strong> 业务侧 [MUST NOT] 直接 import 消费——children 递归靠 <code>MenuItemSub</code> prop 自引用再实例化，仅由 MenuTree 内部驱动。</li></ul><h2 id="api" tabindex="-1">API <a class="header-anchor" href="#api" aria-label="Permalink to &quot;API&quot;">​</a></h2><blockquote><p>⚠️ API 以 types.ts 与组件源码为真相源；与文档冲突时以源码为准。</p></blockquote><h3 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h3><table tabindex="0"><thead><tr><th>name</th><th>type</th><th>默认</th><th>语义</th></tr></thead><tbody><tr><td><code>menu</code></td><td><code>RouteMetaResolveRaw</code>（必填）</td><td>—</td><td>当前分组节点</td></tr><tr><td><code>MenuItemSub</code></td><td><code>any</code>（必填）</td><td>—</td><td>组件自引用，供 children 递归再实例化</td></tr></tbody></table><h3 id="emits" tabindex="-1">Emits <a class="header-anchor" href="#emits" aria-label="Permalink to &quot;Emits&quot;">​</a></h3><p>无</p><h3 id="slots" tabindex="-1">Slots <a class="header-anchor" href="#slots" aria-label="Permalink to &quot;Slots&quot;">​</a></h3><p>无（ElSubMenu 标题与子项均由 menu 数据驱动）</p><h3 id="expose" tabindex="-1">Expose <a class="header-anchor" href="#expose" aria-label="Permalink to &quot;Expose&quot;">​</a></h3><p>无</p><h2 id="反模式-注意" tabindex="-1">反模式 / 注意 <a class="header-anchor" href="#反模式-注意" aria-label="Permalink to &quot;反模式 / 注意&quot;">​</a></h2><ul><li><strong>缺自引用 prop</strong>：children 递归靠 <code>MenuItemSub</code> prop 再实例化，缺它无法递归展开子级</li><li><strong>想在分组形态下把本组件也换成分组标题</strong>：分组标题是视觉聚类不是层级实体，[MUST NOT] 嵌套分组（EP / AntD / shadcn 皆不支持）；L2+ 保持 ElSubMenu 是设计内行为</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>消费方：<code>MenuTree</code>（menu 族）</li><li>数据契约：<code>RouteMetaResolveRaw</code>（@/types）</li></ul>',25)])])}const m=t(i,[["render",n]]);export{p as __pageData,m as default};
